import{z as s,x as A,o as E,c as d,q as r,j as B,D as l,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"T5 相对位置偏置","description":"","frontmatter":{"title":"T5 相对位置偏置","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/t5-relative-bias.md","filePath":"llm/t5-relative-bias.md","lastUpdated":1791413859000}'),p={name:"llm/t5-relative-bias.md"};function D(m,a,f,h,T,_){const i=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="t5-相对位置偏置" tabindex="-1">T5 相对位置偏置 <a class="header-anchor" href="#t5-相对位置偏置" aria-label="Permalink to &quot;T5 相对位置偏置&quot;">​</a></h1><div class="epigraph"><p>我们不用正弦或学习到的绝对位置嵌入，而是在注意力 logits 上加一个随距离变化的标量偏置。</p><footer>—— Raffel et al., Exploring the Limits of Transfer Learning with a Unified Text-to-Text Transformer, JMLR 2020</footer></div><p><a href="/llm/bert-encoder">上一课</a>把双向编码器的层序、段嵌入和 <code>[CLS]</code> 钉死。位置仍是可学习绝对向量，加在嵌入上，最长 512。本课补的缺口：编解码模型若要把任意长度的源与目标送进同一套注意力，绝对下标会先饱和，段嵌入也帮不上跨序列的相对距离。T5 把位置从「加在输入上的向量」改成「加在注意力分数上的偏置」。后课的 BART、前缀掩码都默认你会这种 logits 侧的相对位置，不再回到 BERT 的绝对表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/bert-encoder">BERT 编码器</a>的位置嵌入 \\(p_i\\in\\mathbb{R}^d\\) 与 token 相加，位置是内容的一部分。<a href="/llm/sinusoidal-pe">正弦位置</a>同样作用在输入，只是用封闭公式生成。两种都把「第 \\(i\\) 个槽」当成绝对坐标。编码器–解码器里源长 \\(m\\)、目标长 \\(n\\) 经常超过预训练截断；绝对坐标一溢出，模型看见的是从未训练过的下标，而不是「相距 \\(k\\) 步」。</p><p>Shaw 等人已经把相对位置写进注意力：让 \\(q_i\\) 与 \\(k_j\\) 的相容性依赖 \\(j-i\\)。T5 要的更窄——不必学一组相对键向量，只要在 <a href="/llm/sdpa">SDPA</a> 的分数上加一个标量，让距离成为打分的加性修正。缺口是：<strong>位置信息进 logits，不进嵌入和</strong>。</p><p><span class="marginnote">ALiBi 也是 logits 侧的线性偏置，但是固定斜率、不学习分桶。T5 的偏置可学习、按距离分桶。后课比较外推时不要把两者收成同一种方法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记分数 \\(S_{ij}=q_i^\\top k_j/\\sqrt{d_k}\\)。T5 写成</p> \\[S_{ij}\\leftarrow S_{ij}+b_{\\mathrm{bucket}(j-i)}, \\]<p>\\(b\\) 是每个注意力头一份的可学习向量，下标由距离分桶给出。分桶对近距离一一对应，远距离对数压缩，避免为每个可能的 \\(|j-i|\\) 各养一个参数。偏置只用在两处自注意力：编码器自注意力与解码器掩码自注意力。T5 的<a href="/llm/encoder-decoder-attention">编码器–解码器注意力</a>不加位置偏置：\\(i\\) 与 \\(j\\) 分属目标与源，\\(j-i\\) 不再有自然语义，对齐完全交给内容点积。</p><p>嵌入层不再加位置向量。内容与位置在加法上解耦：token 嵌入只编码身份，距离只改谁更容易被看见。<span class="marginnote">位置进 logits 而不进嵌入，可以类比阅卷加分：不在考卷上标注谁坐前排后排（不改内容），而是在评分时按座位距离加分减分（改分数）。token 身份不变，只是「谁更容易被看见」被距离调整。</span></p><h3 id="分桶而不是全表" tabindex="-1">分桶而不是全表 <a class="header-anchor" href="#分桶而不是全表" aria-label="Permalink to &quot;分桶而不是全表&quot;">​</a></h3><p>若为每个偏移存一个 \\(b\\)，最大长度一涨，参数与缓存都涨。对数分桶把「很远」收成少数几个共享偏置，表达的是粗粒度的远距先验，不是精确的第 407 步。这是相对偏置能接到 512 以外的代价：远距分辨率下降。<span class="marginnote">分桶给个数字实例：距离 1、2、3 各占一个桶，偏置逐位可学；距离几百步时，相邻的多个距离被压进同一个桶、共享同一个偏置——表是「近处逐级精确、远处一档打包」，512 以外也有桶可查，只是查到的是「远」这个档位。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>相对偏置不改变 softmax 的行随机性，只改变哪一列在竞争中占优。头与头可以学到不同的距离偏好：有的头偏近邻，有的头几乎平坦。因为偏置加在缩放点积之后、softmax 之前，它与因果掩码相容——非法位置仍是 \\(-\\infty\\)，合法位置内部再按距离微调。</p><p>交叉注意力里源与目标没有共享绝对坐标，T5 因此不给它任何位置偏置：对齐完全由内容点积做，没有相对桶参与；偏置要打破的置换对称属于自注意力那一侧。</p>',17)),(E(),B(o,null,{default:l(()=>[n(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20D1%5B%22%E8%B7%9D%E7%A6%BB%201%22%5D%20--%3E%20B1%5B%22%E6%A1%B60%EF%BC%9A%E7%B2%BE%E7%A1%AE%E5%81%8F%E7%BD%AE%22%5D%0A%20%20D2%5B%22%E8%B7%9D%E7%A6%BB%202%22%5D%20--%3E%20B2%5B%22%E6%A1%B61%EF%BC%9A%E7%B2%BE%E7%A1%AE%E5%81%8F%E7%BD%AE%22%5D%0A%20%20D3%5B%22%E8%B7%9D%E7%A6%BB%203%20%E5%88%B0%208%22%5D%20--%3E%20B3%5B%22%E8%BF%91%E8%B7%9D%E5%B0%8F%E6%A1%B6%EF%BC%9A%E4%BB%8D%E8%BE%83%E7%BB%86%22%5D%0A%20%20D4%5B%22%E8%B7%9D%E7%A6%BB%20100%20%2F%20407%20%2F%205000%22%5D%20--%3E%20B4%5B%22%E8%BF%9C%E8%B7%9D%E5%AF%B9%E6%95%B0%E6%A1%B6%EF%BC%9A%E5%85%B1%E4%BA%AB%E4%B8%80%E4%B8%AA%E5%81%8F%E7%BD%AE%22%5D%0A%20%20B1%20--%3E%20ADD%5B%22b%20%E5%8A%A0%E5%88%B0%E5%88%86%E6%95%B0%20S_ij%22%5D%0A%20%20B2%20--%3E%20ADD%0A%20%20B3%20--%3E%20ADD%0A%20%20B4%20--%3E%20ADD%0A%20%20ADD%20--%3E%20SM%5B%22softmax%20%E5%89%8D%E5%BE%AE%E8%B0%83%EF%BC%9A%E5%90%88%E6%B3%95%E4%BD%8D%E7%BD%AE%E6%8C%89%E8%B7%9D%E7%A6%BB%E5%86%8D%E5%88%86%E9%85%8D%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">这张图回答的问题是：查表到底怎么发生。每个 token 对按距离 \\(j-i\\) 查桶、取出标量 \\(b\\)，加在缩放点积之后、softmax 之前——近处几个桶一一对应分得细，远处全部打包成少数档位，这就是「能接到 512 以外」与「远距分不开」同一件事的两面。</span></p><p><span class="marginnote">置换对称：若既无位置嵌入也无相对偏置，交换两个源 token 只改内容项。相对偏置让「左边的源」和「右边的源」在分数上可区分，即便内容相似。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>相对偏置不是长度外推的保证。桶表在训练长度内学到的远距值，推到更远时往往落在同一个桶，模型把「更远」当成「已经很远」。T5 的文本生成长度靠相对偏置加编解码结构共同撑起，不要单归因于 \\(b\\)。绝对位置在短编码器、句对分类里仍简单；本课不废除它，只是在编解码主干上换默认。<span class="marginnote">初学者容易以为「相对位置 = 天然支持任意长文本」。桶表在训练长度内学习：推到更远时落在最后一个远距桶，模型只知道「很远」，分不清 1000 步和 5000 步——能接住不等于分得开。</span></p>',4)),(E(),B(o,null,{default:l(()=>[n(i,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22Query%22%5D%20--%3E%20S%5B%22%E7%BC%A9%E6%94%BE%E7%82%B9%E7%A7%AF%22%5D%0A%20%20K%5B%22Key%22%5D%20--%3E%20S%0A%20%20D%5B%22%E7%9B%B8%E5%AF%B9%E8%B7%9D%E7%A6%BB%E5%88%86%E6%A1%B6%22%5D%20--%3E%20B%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E5%81%8F%E7%BD%AE%20b%22%5D%0A%20%20S%20--%3E%20A%5B%22S%20%E5%8A%A0%20b%22%5D%0A%20%20B%20--%3E%20A%0A%20%20A%20--%3E%20M%5B%22%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20P%5B%22Softmax%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[t("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"T5 把位置从输入加法挪到注意力 logits 的相对标量偏置，按距离分桶、按头学习。"),e("li",null,"嵌入不再携带绝对下标；远距分辨率由桶的对数压缩决定。"),e("li",null,"偏置只加在编码器与解码器的自注意力上；T5 的交叉注意力不带位置偏置，对齐完全靠内容点积。"),e("li",null,"分桶能接到训练长度以外，但不等于外推已经解决。"),e("li",null,[t("出处：Raffel et al., "),e("em",null,"T5"),t(", JMLR 2020；相对位置的前身见 Shaw et al., NAACL 2018。")])],-1))])}const u=s(p,[["render",D]]);export{b as __pageData,u as default};
